WITH scored AS (SELECT id, customer_id, end_date, status, LAST_VALUE(monthly_fee) IGNORE NULLS OVER (PARTITION BY plan ORDER BY monthly_fee ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_monthly_fee, LAST_VALUE(monthly_fee) IGNORE NULLS OVER (PARTITION BY plan, customer_id ORDER BY end_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_monthly_fee_2, LAST_VALUE(monthly_fee) IGNORE NULLS OVER (PARTITION BY customer_id ORDER BY start_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_monthly_fee_3 FROM subscriptions) SELECT customer_id, COUNT(*) AS event_count, PERCENTILE_APPROX(last_known_monthly_fee_2, 0.9) AS last_known_monthly_fee_2_p90, COUNT(CASE WHEN status = 'PAUSED' THEN 1 END) AS paused_count, ROUND(AVG(last_known_monthly_fee), 2) AS avg_last_known_monthly_fee FROM scored GROUP BY customer_id HAVING event_count > 1 ORDER BY last_known_monthly_fee_2_p90 DESC;
